        // Fuzz: use prank as non-owner actor, sendMoney with value amount
        vm.prank(actor);
        try c.sendMoney(target, amount) {
            // On success, post-balance must equal preBalance - amount (funds transferred out)
            uint256 postBalance = address(c).balance;
            assertTrue(postBalance == preBalance - amount);
        } catch {
            // If it reverts, the invariant is not violated; skip assertion
        }
    }
}

